'use server'

import { revalidatePath } from 'next/cache'

// Mock database simulation
let notificationsEnabled = false

/**
 * Server Action to toggle the notification preference.
 * Uses revalidatePath to refresh the page without redirection.
 */
export async function toggleNotificationPreference() {
  // Simulate database latency
  await new Promise((resolve) => setTimeout(resolve, 100))

  // Toggle the state
  notificationsEnabled = !notificationsEnabled

  // Revalidate the path to update the UI on the current page
  // This is the recommended Next.js approach for refreshing data after a mutation
  revalidatePath('/')
}

/**
 * Helper to get the current state for rendering
 */
export async function getNotificationPreference() {
  // Simulate database latency
  await new Promise((resolve) => setTimeout(resolve, 50))
  return notificationsEnabled
}

import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  const isEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong></p>

      {/* 
        This form action invokes the Server Action. 
        Upon completion, revalidatePath('/') is called, refreshing the page data
        without a redirect. 
      */}
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Toggle Notification Preference
        </button>
      </form>
    </main>
  );
}
